import sys

data = sys.stdin.read().split()
n = int(data[0]); k = int(data[1])
edges = [(int(data[2 + 2 * i]), int(data[3 + 2 * i])) for i in range(n - 1)]
best = n - 1
for mask in range(1 << (n - 1)):
    cnt = bin(mask).count('1')
    if cnt >= best:
        continue
    dsu = list(range(n))
    def find(x):
        while dsu[x] != x:
            dsu[x] = dsu[dsu[x]]
            x = dsu[x]
        return x
    for i, (u, v) in enumerate(edges):
        if not (mask >> i) & 1:
            a, b = find(u), find(v)
            if a != b:
                dsu[a] = b
    sizes = {}
    for v in range(n):
        r = find(v)
        sizes[r] = sizes.get(r, 0) + 1
    if max(sizes.values()) <= k:
        best = cnt
print(best)

